import { format, formatDistanceToNow, parseISO, isWithinInterval } from 'date-fns'
import type { User, VisibilityPool } from '@/types'

export function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ')
}

export function formatDate(iso: string, pattern = 'MMM d, yyyy') {
  return format(parseISO(iso), pattern)
}

export function timeAgo(iso: string) {
  return formatDistanceToNow(parseISO(iso), { addSuffix: true })
}

export function canView(
  visibility: VisibilityPool,
  user: User,
  opts?: { verticalId?: string; departmentId?: string }
): boolean {
  if (user.role === 'admin' || user.role === 'hr') return true
  if (visibility === 'organization' || visibility === 'leadership') return true
  if (visibility === 'vertical' && opts?.verticalId === user.verticalId) return true
  if (visibility === 'department' && opts?.departmentId === user.departmentId) return true
  return user.visibilityPools.includes(visibility)
}

export function getInitials(name: string) {
  return name
    .split(' ')
    .map((n) => n[0])
    .join('')
    .slice(0, 2)
    .toUpperCase()
}

export function filterByTenant<T extends { verticalId?: string; departmentId?: string; visibility?: VisibilityPool }>(
  items: T[],
  user: User
): T[] {
  return items.filter((item) => {
    if (!item.visibility) return true
    return canView(item.visibility, user, {
      verticalId: item.verticalId,
      departmentId: item.departmentId,
    })
  })
}

export function eventsInRange(events: { start: string; end: string }[], start: Date, end: Date) {
  return events.filter((e) =>
    isWithinInterval(parseISO(e.start), { start, end: parseISO(e.end) > end ? end : parseISO(e.end) })
  )
}

