import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useState,
  type ReactNode,
} from 'react'
import {
  announcements,
  events,
  forumThreads,
  footprints,
  knowledgeDocs,
  leadershipMessages,
  mediaGallery,
  moderationQueue,
  newJoinees,
  recognitions,
  users,
} from '@/data/seed'
import type {
  Announcement,
  ForumThread,
  Recognition,
  User,
} from '@/types'

type AppMode = 'web' | 'mobile' | 'admin'

interface AppState {
  currentUser: User | null
  mode: AppMode
  announcements: Announcement[]
  recognitions: Recognition[]
  forumThreads: ForumThread[]
}

interface AppContextValue extends AppState {
  login: (email: string, password: string) => boolean
  logout: () => void
  setMode: (mode: AppMode) => void
  addRecognition: (rec: Omit<Recognition, 'id' | 'createdAt' | 'reactions' | 'replies' | 'moderated' | 'status'>) => void
  reactToRecognition: (id: string) => void
  addReply: (recognitionId: string, text: string) => void
  publishAnnouncement: (ann: Announcement) => void
  moderateItem: (id: string, status: 'approved' | 'removed') => void
}

const STORAGE_KEY = 'nexus-intranet-session'

const AppContext = createContext<AppContextValue | null>(null)

function loadSession(): User | null {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return null
    const { userId } = JSON.parse(raw) as { userId: string }
    return users.find((u) => u.id === userId) ?? null
  } catch {
    return null
  }
}

export function AppProvider({ children }: { children: ReactNode }) {
  const [currentUser, setCurrentUser] = useState<User | null>(loadSession)
  const [mode, setMode] = useState<AppMode>('web')
  const [annState, setAnnState] = useState(announcements)
  const [recState, setRecState] = useState(recognitions)
  const [forumState, setForumState] = useState(forumThreads)
  const [modState, setModState] = useState(moderationQueue)

  const login = useCallback((email: string, password: string) => {
    const user = users.find(
      (u) => u.email.toLowerCase() === email.toLowerCase() && u.password === password
    )
    if (!user) return false
    setCurrentUser(user)
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ userId: user.id }))
    if (user.role === 'admin' || user.role === 'hr') setMode('admin')
    else setMode('web')
    return true
  }, [])

  const logout = useCallback(() => {
    setCurrentUser(null)
    localStorage.removeItem(STORAGE_KEY)
    setMode('web')
  }, [])

  const addRecognition = useCallback(
    (rec: Omit<Recognition, 'id' | 'createdAt' | 'reactions' | 'replies' | 'moderated' | 'status'>) => {
      const newRec: Recognition = {
        ...rec,
        id: `rec-${Date.now()}`,
        createdAt: new Date().toISOString(),
        reactions: 0,
        replies: [],
        moderated: false,
        status: 'active',
      }
      setRecState((prev) => [newRec, ...prev])
    },
    []
  )

  const reactToRecognition = useCallback((id: string) => {
    setRecState((prev) =>
      prev.map((r) => (r.id === id ? { ...r, reactions: r.reactions + 1 } : r))
    )
  }, [])

  const addReply = useCallback((recognitionId: string, text: string) => {
    if (!currentUser) return
    setRecState((prev) =>
      prev.map((r) =>
        r.id === recognitionId
          ? {
              ...r,
              replies: [
                ...r.replies,
                {
                  id: `reply-${Date.now()}`,
                  userId: currentUser.id,
                  text,
                  createdAt: new Date().toISOString(),
                },
              ],
            }
          : r
      )
    )
  }, [currentUser])

  const publishAnnouncement = useCallback((ann: Announcement) => {
    setAnnState((prev) => [{ ...ann, status: 'published' as const }, ...prev])
  }, [])

  const moderateItem = useCallback((id: string, status: 'approved' | 'removed') => {
    setModState((prev) =>
      prev.map((m) => (m.id === id ? { ...m, status } : m))
    )
    if (status === 'removed') {
      const item = modState.find((m) => m.id === id)
      if (item?.type === 'recognition') {
        setRecState((prev) =>
          prev.map((r) =>
            r.id === item.contentId ? { ...r, status: 'hidden' as const } : r
          )
        )
      }
    }
  }, [modState])

  const value = useMemo<AppContextValue>(
    () => ({
      currentUser,
      mode,
      announcements: annState,
      recognitions: recState,
      forumThreads: forumState,
      login,
      logout,
      setMode,
      addRecognition,
      reactToRecognition,
      addReply,
      publishAnnouncement,
      moderateItem,
    }),
    [
      currentUser,
      mode,
      annState,
      recState,
      forumState,
      login,
      logout,
      addRecognition,
      reactToRecognition,
      addReply,
      publishAnnouncement,
      moderateItem,
    ]
  )

  return <AppContext.Provider value={value}>{children}</AppContext.Provider>
}

export function useApp() {
  const ctx = useContext(AppContext)
  if (!ctx) throw new Error('useApp must be used within AppProvider')
  return ctx
}

export { users, events, footprints, leadershipMessages, knowledgeDocs, mediaGallery, newJoinees, moderationQueue, departments, verticals, leaderboard }
