import { useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { useApp } from '@/context/AppContext'
import { filterByTenant, timeAgo, canView } from '@/lib/utils'
import { users } from '@/data/seed'

export function Announcements() {
  const { currentUser, announcements } = useApp()
  const [filter, setFilter] = useState<string>('all')
  if (!currentUser) return null

  const published = filterByTenant(
    announcements.filter((a) => a.status === 'published'),
    currentUser
  )
  const filtered =
    filter === 'all' ? published : published.filter((a) => a.type === filter)

  return (
    <div className="page-container space-y-6 animate-fade-in">
      <div>
        <h1 className="font-display text-2xl font-bold">News & Business Updates</h1>
        <p className="text-slate-500 mt-1">Announcements, project wins, and milestones — tenant-aware visibility.</p>
      </div>
      <div className="flex flex-wrap gap-2">
        {['all', 'company', 'business', 'project-win', 'milestone'].map((f) => (
          <button
            key={f}
            onClick={() => setFilter(f)}
            className={`px-3 py-1.5 rounded-full text-sm font-medium ${
              filter === f ? 'bg-brand-600 text-white' : 'bg-white border border-slate-200 text-slate-600'
            }`}
          >
            {f === 'all' ? 'All' : f.replace('-', ' ')}
          </button>
        ))}
      </div>
      <div className="grid gap-4">
        {filtered.map((ann) => {
          const author = users.find((u) => u.id === ann.authorId)
          const locked = !canView(ann.visibility, currentUser, {
            verticalId: ann.verticalId,
            departmentId: ann.departmentId,
          })
          return (
            <Card key={ann.id} className={locked ? 'opacity-50' : ''}>
              <CardHeader>
                <div className="flex flex-wrap gap-2">
                  <Badge color="brand">{ann.type}</Badge>
                  <Badge>{ann.visibility}</Badge>
                  {ann.featured && <Badge color="warning">Featured</Badge>}
                </div>
                <CardTitle className="mt-2">{ann.title}</CardTitle>
                <p className="text-sm text-slate-500">
                  {author?.name} · {timeAgo(ann.publishedAt)}
                </p>
              </CardHeader>
              <CardContent className="pt-0">
                <p className="text-slate-600">{ann.body}</p>
                <div className="flex gap-2 mt-3">
                  {ann.tags.map((t) => (
                    <span key={t} className="text-xs text-slate-400">#{t}</span>
                  ))}
                </div>
              </CardContent>
            </Card>
          )
        })}
      </div>
    </div>
  )
}

import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { useApp } from '@/context/AppContext'
import { footprints, departments, verticals, users } from '@/context/AppContext'
import { filterByTenant } from '@/lib/utils'

export function Footprints() {
  const { currentUser } = useApp()
  if (!currentUser) return null
  const visible = filterByTenant(footprints, currentUser)

  return (
    <div className="page-container space-y-6 animate-fade-in">
      <div>
        <h1 className="font-display text-2xl font-bold">Impact Footprints</h1>
        <p className="text-slate-500 mt-1">Department and vertical impact — breaking silos with visible outcomes.</p>
      </div>
      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
        {visible.map((fp) => {
          const dept = departments.find((d) => d.id === fp.departmentId)
          const vert = verticals.find((v) => v.id === fp.verticalId)
          return (
            <Card key={fp.id} className="overflow-hidden">
              <div className="h-1.5" style={{ background: dept?.color ?? '#6366f1' }} />
              <CardHeader>
                <Badge>{fp.quarter}</Badge>
                <CardTitle className="mt-2 text-lg">{fp.teamName}</CardTitle>
                <p className="text-xs text-slate-500">{vert?.name} · {dept?.name}</p>
              </CardHeader>
              <CardContent className="pt-0">
                <p className="text-sm text-slate-600">{fp.impact}</p>
                <div className="grid grid-cols-3 gap-2 mt-4">
                  {fp.metrics.map((m) => (
                    <div key={m.label} className="text-center p-2 rounded-lg bg-slate-50">
                      <p className="text-lg font-bold text-brand-700">{m.value}</p>
                      <p className="text-xs text-slate-500">{m.label}</p>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )
        })}
      </div>
    </div>
  )
}

import { useMemo, useState } from 'react'
import {
  format,
  startOfMonth,
  endOfMonth,
  eachDayOfInterval,
  isSameDay,
  parseISO,
  isSameMonth,
} from 'date-fns'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Badge } from '@/components/ui/Badge'
import { events } from '@/context/AppContext'
import { formatDate } from '@/lib/utils'

const typeColors: Record<string, string> = {
  townhall: 'brand',
  celebration: 'warning',
  workshop: 'brand',
  volunteer: 'success',
  social: 'default',
}

export function CalendarPage() {
  const [month, setMonth] = useState(new Date())
  const days = useMemo(() => {
    const start = startOfMonth(month)
    const end = endOfMonth(month)
    return eachDayOfInterval({ start, end })
  }, [month])

  const eventsByDay = useMemo(() => {
    const map = new Map<string, typeof events>()
    events.forEach((ev) => {
      const key = format(parseISO(ev.start), 'yyyy-MM-dd')
      if (!map.has(key)) map.set(key, [])
      map.get(key)!.push(ev)
    })
    return map
  }, [])

  return (
    <div className="page-container space-y-6 animate-fade-in">
      <div className="flex flex-wrap items-center justify-between gap-4">
        <div>
          <h1 className="font-display text-2xl font-bold">Engagement Calendar</h1>
          <p className="text-slate-500 mt-1">Townhalls, celebrations, workshops, and volunteer drives.</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() - 1))}
            className="px-3 py-1.5 rounded-lg border border-slate-200 text-sm"
          >
            Prev
          </button>
          <span className="px-4 py-1.5 font-display font-semibold">{format(month, 'MMMM yyyy')}</span>
          <button
            onClick={() => setMonth(new Date(month.getFullYear(), month.getMonth() + 1))}
            className="px-3 py-1.5 rounded-lg border border-slate-200 text-sm"
          >
            Next
          </button>
        </div>
      </div>

      <Card>
        <CardContent className="pt-5">
          <div className="grid grid-cols-7 gap-1 text-center text-xs font-medium text-slate-500 mb-2">
            {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map((d) => (
              <div key={d}>{d}</div>
            ))}
          </div>
          <div className="grid grid-cols-7 gap-1">
            {Array.from({ length: days[0].getDay() }).map((_, i) => (
              <div key={`pad-${i}`} />
            ))}
            {days.map((day) => {
              const key = format(day, 'yyyy-MM-dd')
              const dayEvents = eventsByDay.get(key) ?? []
              return (
                <div
                  key={key}
                  className={`min-h-[72px] p-1 rounded-lg border text-left ${
                    isSameMonth(day, month) ? 'border-slate-100 bg-white' : 'border-transparent opacity-40'
                  } ${isSameDay(day, new Date()) ? 'ring-2 ring-brand-500' : ''}`}
                >
                  <span className="text-xs font-medium text-slate-600">{format(day, 'd')}</span>
                  {dayEvents.slice(0, 2).map((ev) => (
                    <div
                      key={ev.id}
                      className="mt-0.5 text-[10px] truncate px-1 rounded text-white"
                      style={{ background: ev.color }}
                      title={ev.title}
                    >
                      {ev.title}
                    </div>
                  ))}
                </div>
              )
            })}
          </div>
        </CardContent>
      </Card>

      <div className="grid md:grid-cols-2 gap-4">
        {events.map((ev) => (
          <Card key={ev.id}>
            <CardHeader className="flex flex-row items-start justify-between">
              <div>
                <CardTitle className="text-base">{ev.title}</CardTitle>
                <p className="text-sm text-slate-500 mt-1">{formatDate(ev.start, 'EEE, MMM d · h:mm a')}</p>
              </div>
              <Badge color={typeColors[ev.type] as 'brand'}>{ev.type}</Badge>
            </CardHeader>
            <CardContent className="pt-0 text-sm text-slate-600">
              {ev.description} · {ev.location} · {ev.attendees} attending
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  )
}

import { useState } from 'react'
import { Heart, MessageCircle, ThumbsUp } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card'
import { Button } from '@/components/ui/Button'
import { Avatar } from '@/components/ui/Avatar'
import { Badge } from '@/components/ui/Badge'
import { Input, Textarea } from '@/components/ui/Input'
import { useApp } from '@/context/AppContext'
import { users, leaderboard } from '@/context/AppContext'
import { timeAgo } from '@/lib/utils'

export function Recognition() {
  const { currentUser, recognitions, addRecognition, reactToRecognition, addReply } = useApp()
  const [toId, setToId] = useState('')
  const [message, setMessage] = useState('')
  const [replyText, setReplyText] = useState<Record<string, string>>({})
  if (!currentUser) return null

  const active = recognitions.filter((r) => r.status !== 'hidden')

  const submit = () => {
    if (!toId || !message.trim()) return
    addRecognition({
      fromUserId: currentUser.id,
      toUserId: toId,
      message: message.trim(),
      category: 'peer',
    })
    setMessage('')
    setToId('')
  }

  return (
    <div className="page-container space-y-6 animate-fade-in">
      <div>
        <h1 className="font-display text-2xl font-bold">Recognition & Celebration</h1>
        <p className="text-slate-500 mt-1">Peer appreciation, achievements, replies, and leaderboards.</p>
      </div>

      <div className="grid lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2">
          <CardHeader>
            <CardTitle>Give kudos</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3 pt-0">
            <select
              value={toId}
              onChange={(e) => setToId(e.target.value)}
              className="w-full px-4 py-2.5 rounded-xl border border-slate-200"
            >
              <option value="">Select colleague</option>
              {users.filter((u) => u.id !== currentUser.id).map((u) => (
                <option key={u.id} value={u.id}>{u.name}</option>
              ))}
            </select>
            <Textarea
              placeholder="What did they do that deserves recognition?"
              value={message}
              onChange={(e) => setMessage(e.target.value)}
            />
            <Button onClick={submit}>
              <Heart className="w-4 h-4" /> Send appreciation
            </Button>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-base">Points leaderboard</CardTitle>
          </CardHeader>
          <CardContent className="space-y-2 pt-0">
            {leaderboard.map((e) => (
              <div key={e.userId} className="flex items-center gap-2 text-sm py-1">
                <span className="w-6 font-mono text-slate-400">#{e.rank}</span>
                <span className="flex-1">{e.name}</span>
                <span className="font-semibold text-brand-600">{e.points}</span>
              </div>
            ))}
          </CardContent>
        </Card>
      </div>

      <div className="space-y-4">
        {active.map((rec) => {
          const from = users.find((u) => u.id === rec.fromUserId)
          const to = users.find((u) => u.id === rec.toUserId)
          return (
            <Card key={rec.id} className={rec.status === 'flagged' ? 'border-amber-200' : ''}>
              <CardContent className="pt-5">
                <div className="flex gap-3">
                  <Avatar src={from?.avatar} name={from?.name ?? '?'} />
                  <div className="flex-1">
                    <p className="text-sm">
                      <span className="font-medium">{from?.name}</span>
                      <span className="text-slate-500"> → </span>
                      <span className="font-medium">{to?.name}</span>
                    </p>
                    <div className="flex gap-2 mt-1">
                      <Badge color={rec.category === 'welcome' ? 'success' : 'brand'}>{rec.category}</Badge>
                      {rec.status === 'flagged' && <Badge color="warning">Under review</Badge>}
                    </div>
                    <p className="text-slate-700 mt-2">{rec.message}</p>
                    <p className="text-xs text-slate-400 mt-1">{timeAgo(rec.createdAt)}</p>
                    <div className="flex items-center gap-4 mt-3">
                      <button
                        onClick={() => reactToRecognition(rec.id)}
                        className="flex items-center gap-1 text-sm text-slate-600 hover:text-brand-600"
                      >
                        <ThumbsUp className="w-4 h-4" /> {rec.reactions}
                      </button>
                      <span className="flex items-center gap-1 text-sm text-slate-500">
                        <MessageCircle className="w-4 h-4" /> {rec.replies.length} replies
                      </span>
                    </div>
                    {rec.replies.map((r) => {
                      const ru = users.find((u) => u.id === r.userId)
                      return (
                        <p key={r.id} className="text-sm text-slate-600 mt-2 pl-4 border-l-2 border-slate-100">
                          <span className="font-medium">{ru?.name}:</span> {r.text}
                        </p>
                      )
                    })}
                    <div className="flex gap-2 mt-2">
                      <Input
                        placeholder="Add a reply..."
                        value={replyText[rec.id] ?? ''}
                        onChange={(e) => setReplyText((p) => ({ ...p, [rec.id]: e.target.value }))}
                        className="flex-1"
                      />
                      <Button
                        size="sm"
                        variant="secondary"
                        onClick={() => {
                          const t = replyText[rec.id]
                          if (t?.trim()) {
                            addReply(rec.id, t.trim())
                            setReplyText((p) => ({ ...p, [rec.id]: '' }))
                          }
                        }}
                      >
                        Reply
                      </Button>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          )
        })}
      </div>
    </div>
  )
}

